import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`amazon-store`,heroTitle:`Build your Amazon ad keywords in minutes`,heroSubtitle:`Perplexity Computer analyzes your products, builds keyword lists across match types, and delivers bid-ready bulk upload sheets — automatically.`,heroCta:`Get Started`,inputUrlCta:`Build my keywords`,inputUrlPlaceholder:`www.amazon.com/stores/yourstore`,inputUrlPrefill:`Go to {url} and build a complete Amazon Sponsored Products keyword strategy. Analyze every product listing — titles, bullet points, descriptions, and backend search terms. For each product: (1) Research high-converting search terms from Amazon autocomplete, competitor listings, and category best sellers, (2) Build keyword lists across broad, phrase, and exact match types with recommended daily bids based on competition level, (3) Generate negative keyword lists to block irrelevant traffic and wasted spend, (4) Create product-targeting campaigns for competitor ASINs worth conquesting, (5) Estimate daily budget, impressions, and ACoS at different bid levels. Deliver everything as an Amazon bulk upload sheet — campaigns, ad groups, keywords, match types, bids, and negatives — ready to import into Seller Central or your ad management tool.`,heroOverlaySteps:[`Analyzing your product listings for keywords, categories, and competitors`,`Researching high-converting search terms across Amazon autocomplete and BSR`,`Building keyword lists with match types, bids, and negative keywords`,`Bulk upload sheet with campaigns, bids, and negatives — ready to import`],generatingSteps:[`Visiting {url} to extract your product listings, categories, and competitors`,`Designing an agent to research Amazon search terms and competitor ASINs`,`Configuring keyword lists with match types, bid recommendations, and negatives`,`Setting up bulk upload sheet formatted for Seller Central import`],featureSectionTitle:`From store to ad campaigns`,featureCardTitles:[`Connects to your Amazon tools`,`Campaigns ready to upload`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Shopify, Google Sheets, Airtable, Notion — Computer delivers keyword lists and bulk sheets in the format your ad tools expect.`,`Keyword lists. Match types. Bid recommendations. Negative keywords. Computer delivers a bulk upload sheet you can import into Seller Central immediately.`],capabilitySectionTitle:`Your Amazon PPC team, on demand`,capabilitySectionSubtitle:`Paste your store URL, get back a complete keyword strategy.`,capabilityCards:[{title:`Keyword Mining`,description:`Computer finds high-converting search terms from Amazon autocomplete, competitor listings, and category best sellers — matched to your products.`},{title:`Match Type Strategy`,description:`Computer builds keyword lists across broad, phrase, and exact match types — with recommended bids calibrated to competition and conversion potential.`},{title:`Negative Keywords`,description:`Computer generates negative keyword lists to block irrelevant searches — cutting wasted ad spend before you launch a single campaign.`},{title:`ASIN Targeting`,description:`Computer identifies competitor ASINs worth conquesting and builds product-targeting campaigns — so your ads show on their listings.`},{title:`Learns Your Catalog`,description:`Computer remembers your products, categories, and past campaigns across sessions — so every keyword refresh builds on what came before.`},{title:`Weekly Keyword Updates`,description:`Computer monitors search term performance and competitor moves — and alerts you when new keywords emerge or bids need adjusting.`}]});export{t as default};
